 static void ResizeOperationControls(FlowLayoutPanel operations,int widthAvailable){int available=Math.Max(1,widthAvailable-operations.Padding.Horizontal),used=0,rowHeight=0,total=operations.Padding.Vertical;foreach(Control item in operations.Controls){int width=item.Width+item.Margin.Horizontal,height=item.Height+item.Margin.Vertical;if(used>0&&used+width>available){total+=rowHeight;rowHeight=0;used=0;}used+=width;rowHeight=Math.Max(rowHeight,height);}int desired=total+rowHeight;if(operations.Height!=desired)operations.Height=desired;}
 void InstallMonitorHeaders(){preview.ShowHeadingTitle=false;program.ShowHeadingTitle=false;previewFrame=WrapMonitor(monitorSplit.Panel1,"PreviewFrame","PREVIEW",previewLamp,previewStart,previewOutputStatus);programFrame=WrapMonitor(monitorSplit.Panel2,"ProgramFrame","PROGRAM",programLamp,start,programSource);}
 void CopyPreviewResolution(){if(output!=null||previewOutput!=null){configNotice.Text="Arresta entrambi i flussi prima di cambiare risoluzione.";return;}if(selected==null||selectedSource==null){configNotice.Text="Seleziona prima un asset valido nella Preview.";return;}try{Size size=VideoTools.IsVideo(SourcePath(selected))?VideoMetadata.Dimensions(SourcePath(selected)):selectedSource.Size;if(size.Width<16||size.Width>3840||size.Width%2!=0||size.Height<16||size.Height>2160)throw new ArgumentException("Risoluzione sorgente fuori dai limiti NDI (larghezza pari, 16–3840 × 16–2160).");width.Value=size.Width;height.Value=size.Height;configNotice.Text="Risoluzione Preview copiata: "+size.Width+" × "+size.Height+". FPS invariati.";Save();}catch(Exception e){configNotice.Text=e.Message;}}
 static Panel WrapMonitor(Control parent,string name,string title,Label lamp,Button button,Label source){var frame=new Panel{Name=name,Dock=DockStyle.Fill,Padding=new Padding(4)};foreach(Control child in parent.Controls.Cast<Control>().ToArray()){parent.Controls.Remove(child);frame.Controls.Add(child);}var bar=new TableLayoutPanel{Name=name+"Header",Dock=DockStyle.Top,Height=48,ColumnCount=4,Padding=new Padding(6,5,6,5)};bar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,90));bar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,168));bar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,95));bar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));bar.Controls.Add(new Label{Text=title,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,Font=new Font(SystemFonts.DefaultFont,FontStyle.Bold)},0,0);button.Dock=DockStyle.Fill;button.AutoSize=false;button.Margin=new Padding(4,1,0,1);bar.Controls.Add(button,1,0);lamp.Dock=DockStyle.Fill;bar.Controls.Add(lamp,2,0);source.Dock=DockStyle.Fill;source.TextAlign=ContentAlignment.MiddleLeft;bar.Controls.Add(source,3,0);frame.Controls.Add(bar);parent.Controls.Add(frame);return frame;}
 void ApplyShellTheme(){bool dark=darkMode!=null&&darkMode.Checked;Color surface=dark?Color.FromArgb(38,40,44):SystemColors.Control;Color text=dark?Color.Gainsboro:SystemColors.ControlText;ApplyThemeTree(this,surface,text);folderNotification.ForeColor=Color.Red;if(settingsWindow!=null)ApplyThemeTree(settingsWindow,surface,text);files.SetDarkMode(dark);RefreshOutputIndicators();}
 static void ApplyThemeTree(Control root,Color surface,Color text){if(root is PreviewCanvas||root is CountdownLabel||root is AudioMeterControl||root is VideoTransportBar)return;if(root is TextBox||root is NumericUpDown||root is ComboBox||root is ListBox||root is ListView){root.BackColor=surface==SystemColors.Control?SystemColors.Window:Color.FromArgb(52,54,58);root.ForeColor=text;}else if(root is TrackBar){root.BackColor=surface;root.ForeColor=text;}else if(root is Button){root.BackColor=surface;root.ForeColor=text;((Button)root).UseVisualStyleBackColor=false;}else if(root is Panel||root is TableLayoutPanel||root is FlowLayoutPanel||root is TabPage||root is TabControl||root is Form||root is GroupBox){root.BackColor=surface;root.ForeColor=text;}else if(root is Label||root is CheckBox){root.ForeColor=text;}foreach(Control child in root.Controls)ApplyThemeTree(child,surface,text);}
 void ApplyMonitorFrameColors(){Color programColor=output!=null&&output.Error==null?Color.FromArgb(150,20,25):Color.Black;Color previewColor=previewOutput!=null&&previewOutput.Error==null?Color.FromArgb(23,105,57):Color.Black;SetFrameColor(programFrame,programColor);SetFrameColor(previewFrame,previewColor);if(preview.BackColor!=previewColor)preview.BackColor=previewColor;}
 static void SetFrameColor(Panel frame,Color color){if(frame==null)return;frame.BackColor=color;var bar=frame.Controls.OfType<TableLayoutPanel>().FirstOrDefault();if(bar==null)return;bar.BackColor=color;foreach(Control item in bar.Controls)if(item is Label)item.ForeColor=Color.White;}
 void RunSettingsAction(Action action){var window=settingsWindow;if(window!=null)window.Hide();try{action();}finally{if(window!=null&&!window.IsDisposed){window.Show(this);window.Activate();}}}
 void ShowSettingsWindow(){if(settingsWindow!=null&&!settingsWindow.IsDisposed){settingsWindow.Activate();return;}LoadCountdownEditor();settingsWindow=new Form{Text="Impostazioni NDIPlayer",Name="SettingsWindow",Size=new Size(800,460),MinimumSize=new Size(720,400),StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false};settingsWindow.Controls.Add(settingsTabs);settingsTabs.Visible=true;settingsWindow.FormClosed+=delegate{if(!IsDisposed){settingsStorage.Controls.Add(settingsTabs);Save();}settingsWindow=null;};ApplyShellTheme();settingsWindow.Show(this);}
